import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv/dist/ajv.js';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

function validationFailure(error: ErrorObject | undefined): ToolResponse {
  const legacyPath = (error as (ErrorObject & {dataPath?: string}) | undefined)?.dataPath;
  const path = error?.instancePath || legacyPath?.replace(/\./g, '/') || '';
  const property =
    error?.keyword === 'required'
      ? error.params.missingProperty
      : error?.keyword === 'additionalProperties'
        ? error.params.additionalProperty
        : undefined;
  const separator = path || error?.keyword === 'additionalProperties' ? '/' : '';
  const field =
    property === undefined
      ? path || 'input'
      : `${path}${separator}${String(property).replace(/~/g, '~0').replace(/\//g, '~1')}`;
  const constraint = error?.keyword === 'required' ? 'is required' : error?.message || 'is invalid';
  return {result: `Input validation failed: ${field} ${constraint}`};
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly validator = new Ajv({strict: false, validateFormats: false} as unknown as ConstructorParameters<
    typeof Ajv
  >[0]);
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validate: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validate = this.validator.compile(resolved.inputSchema);
      } catch (error) {
        throw new Error(`Invalid inputSchema for tool ${resolved.name}: ${String(error)}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** See specs/hal-engine-tool-input-validation/spec.md for rejection and unknown-tool behavior. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    let validate = tool.validate ?? this.dynamicValidators.get(definition.inputSchema);
    if (!validate) {
      validate = this.validator.compile(definition.inputSchema);
      this.dynamicValidators.set(definition.inputSchema, validate);
    }
    if (!validate(input)) {
      const rejection = validationFailure(validate.errors?.[0]);
      log.warn('tool', 'input validation failed', {name, reason: rejection.result});
      return rejection;
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';
import type {ToolDefinition} from '../../types/ai.js';
import {setLogger} from '../../shared/logger.js';

function registerWeather(inputSchema: ToolDefinition['inputSchema']) {
  const registry = new ToolRegistry();
  let calls = 0;
  registry.register({name: 'weather', description: 'Get weather', inputSchema}, async () => {
    calls += 1;
    return 'sunny';
  });
  return {registry, getCalls: () => calls};
}

describe('ToolRegistry input validation', () => {
  it('rejects an enum mismatch before executing (specs/hal-engine-tool-input-validation/spec.md#5)', async () => {
    const {registry, getCalls} = registerWeather({
      type: 'object',
      properties: {unit: {type: 'string', enum: ['celsius', 'fahrenheit']}},
      required: ['unit'],
    });

    const warnings: string[] = [];
    setLogger({
      debug: () => {},
      info: () => {},
      warn: (category, message, fields) => warnings.push(JSON.stringify({category, message, fields})),
      error: () => {},
    });
    try {
      const response = await registry.execute('weather', {unit: 'kelvin'});
      const warningText = warnings.join(' ');

      expect({
        resultNamesField: response.result.includes('/unit'),
        resultNamesConstraint: response.result.includes('allowed values'),
        resultLeaksValue: response.result.includes('kelvin'),
        logNamesField: warningText.includes('/unit'),
        logNamesConstraint: warningText.includes('allowed values'),
        logLeaksValue: warningText.includes('kelvin'),
        calls: getCalls(),
      }).toEqual({
        resultNamesField: true,
        resultNamesConstraint: true,
        resultLeaksValue: false,
        logNamesField: true,
        logNamesConstraint: true,
        logLeaksValue: false,
        calls: 0,
      });
    } finally {
      setLogger();
    }
  });

  it('names the full path of a missing nested property (specs/hal-engine-tool-input-validation/spec.md#3)', async () => {
    const {registry, getCalls} = registerWeather({
      type: 'object',
      properties: {address: {type: 'object', properties: {street: {type: 'string'}}, required: ['street']}},
      required: ['address'],
    });

    const response = await registry.execute('weather', {address: {}});

    expect({response, calls: getCalls()}).toEqual({
      response: {result: 'Input validation failed: /address/street is required'},
      calls: 0,
    });
  });

  it('reuses the static schema compiled at registration (specs/hal-engine-tool-input-validation/spec.md#9)', async () => {
    const registry = new ToolRegistry();
    const locationSchema = {type: 'string'};
    const inputSchema = {type: 'object', properties: {location: locationSchema}};
    registry.register({name: 'weather', description: 'Get weather', inputSchema}, async () => 'sunny');

    locationSchema.type = 'number';
    const results = await Promise.all(Array.from({length: 10}, () => registry.execute('weather', {location: 'Paris'})));

    expect(results.map(response => response.result)).toEqual(Array(10).fill('sunny'));
  });

  it('escapes separators in missing property paths (specs/hal-engine-tool-input-validation/spec.md#3)', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Get weather',
        inputSchema: {
          type: 'object',
          properties: {
            address: {type: 'object', properties: {'street/name': {type: 'string'}}, required: ['street/name']},
          },
        },
      },
      async () => 'sunny'
    );

    expect(await registry.execute('weather', {address: {}})).toEqual({
      result: 'Input validation failed: /address/street~1name is required',
    });
  });

  it('returns a required-field rejection before executing (specs/hal-engine-tool-input-validation/spec.md#3)', async () => {
    const {registry, getCalls} = registerWeather({
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    });

    const response = await registry.execute('weather', {});

    expect({result: response.result, calls: getCalls()}).toEqual({
      result: 'Input validation failed: location is required',
      calls: 0,
    });
  });

  it('names a forbidden extra property without exposing its value (specs/hal-engine-tool-input-validation/spec.md#7)', async () => {
    const {registry, getCalls} = registerWeather({type: 'object', additionalProperties: false});
    const response = await registry.execute('weather', {secret: '123456789'});

    expect({
      namesPath: response.result.includes('/secret'),
      namesConstraint: response.result.includes('additional properties'),
      leaksValue: response.result.includes('123456789'),
      calls: getCalls(),
    }).toEqual({namesPath: true, namesConstraint: true, leaksValue: false, calls: 0});
  });
});
